@startuml

class ProjectManager {}

class Project {
  + startDate : date
  + endDate : date
  + initiate() : void
  + terminate() : void
}

abstract class WorkProduct {
  + description : string
  + percentComplete : float
  + validate() : void
}

class Requirement extends WorkProduct {}

class System extends WorkProduct {}

class Publication {
  + media : string
}

class Platform {
  + name : string
}

